function calculateVendorTierScore(values = {}) { const piiExposure = clampNumeric(values.piiExposure, 1, 5, 0); const securityMaturity = clampNumeric(values.securityMaturity, 1, 5, 0); const financial = clampNumeric(values.financial, 1, 5, 0); const reputation = clampNumeric(values.reputation, 1, 5, 0); const total = piiExposure * 40 + securityMaturity * 30 + financial * 10 + reputation * 20; return { piiExposure, securityMaturity, financial, reputation, total }; }
function clampNumeric(value, min, max, fallback) { const number = Number(value); if (!Number.isFinite(number)) return fallback; return Math.min(max, Math.max(min, number)); }
function determineQuestionnaireRiskTier(score) { const value = Number(score); if (!Number.isFinite(value) || value <= 0) return 'Tier 1 (High)'; if (value <= 200) return 'Tier 1 (High)'; if (value <= 350) return 'Tier 2 (Medium)'; return 'Tier 3 (Low)'; }
function riskLevelForTier(tier) { return tier === 'Tier 1 (High)' || tier === 'High Risk (Tier 1)' ? 'High Risk (Tier 1)' : tier === 'Tier 2 (Medium)' || tier === 'Medium Risk (Tier 2)' ? 'Medium Risk (Tier 2)' : 'Low Risk (Tier 3)'; }
function riskTierClass(value) { const risk = String(value || '').toLowerCase(); return risk.includes('high') || risk.includes('tier 1') ? 'tier-high' : risk.includes('medium') || risk.includes('tier 2') ? 'tier-medium' : risk.includes('low') || risk.includes('tier 3') ? 'tier-low' : ''; }
function updateQuestionnaireTierFromInputs() { const values = calculateVendorTierScore({ piiExposure: $('questionnairePiiExposure').value, securityMaturity: $('questionnaireSecurityMaturity').value, financial: $('questionnaireFinancial').value, reputation: $('questionnaireReputation').value }); $('questionnaireRiskScore').value = values.total; $('questionnaireRiskTier').value = determineQuestionnaireRiskTier(values.total); return values; }
function renderQuestionnaireSections(responses = {}, sections = null) { const useSections = sections || questionnaireSections; $('questionnaireSections').innerHTML = useSections.map(([title, questions]) => `<fieldset class="questionnaire-section"><legend>${title}</legend>${questions.map((question, index) => { const key = `${title}-${index}`; const decisionKey = `${key}-decision`; const decision = responses[decisionKey] || ''; return `<div class="questionnaire-question"><label>${escapeHtml(question)}</label><div class="questionnaire-decision" role="group" aria-label="Answer Yes or No"><button class="attachment-action-button ${decision === 'Yes' ? 'selected' : ''}" type="button" data-questionnaire-decision="Yes" aria-pressed="${decision === 'Yes'}">Yes</button><button class="attachment-action-button ${decision === 'No' ? 'selected' : ''}" type="button" data-questionnaire-decision="No" aria-pressed="${decision === 'No'}">No</button><input type="hidden" data-questionnaire-decision-value="${escapeHtml(decisionKey)}" value="${escapeHtml(decision)}"></div><label>Answer / details<textarea rows="2" data-questionnaire-answer="${escapeHtml(key)}">${escapeHtml(responses[key] || '')}</textarea></label></div>`; }).join('')}</fieldset>`).join(''); }
function startQuestionnaire(row, template) { const responses = row.responses || {}; $('questionnaireAssessmentId').value = row.id; $('questionnaireAssessmentTitle').textContent = row.vendorName; $('questionnaireAssessmentStatus').textContent = row.status === 'Final' ? 'Review completed questionnaire' : 'Fill in the vendor questionnaire'; renderQuestionnaireSections(responses, template ? template.sections : questionnaireSections); $('questionnaireAssessmentModal').showModal(); }
