async function saveQuestionnaire(event) { event.preventDefault(); const id = $('questionnaireId').value; const assessmentResult = $('questionnaireResult').value; const status = ['Approved', 'Approved with Conditions', 'Rejected'].includes(assessmentResult) ? 'Final' : $('questionnaireStatusValue').value; const row = questionnaireRows.find(item => String(item.id) === id); const values = updateQuestionnaireFormRiskScore(); const responses = { ...(row?.responses || {}), piiExposure: $('questionnaireFormPiiExposure').value, securityMaturity: $('questionnaireFormSecurityMaturity').value, financial: $('questionnaireFormFinancial').value, reputation: $('questionnaireFormReputation').value, riskScore: values.total, riskTier: determineQuestionnaireRiskTier(values.total), assessmentResult }; const data = { vendorName: $('questionnaireVendorName').value, status, reviewDate: $('questionnaireReviewDate').value, result: assessmentResult, reviewer: $('questionnaireReviewer').value, notes: $('questionnaireNotes').value, responses }; const response = await fetch(id ? `/api/tprm-questionnaires/${id}` : '/api/tprm-questionnaires', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); if (!response.ok) { $('questionnaireStatus').textContent = (await response.json().catch(() => ({}))).error || 'Save failed'; return; } resetQuestionnaireForm(); $('questionnaireModal').close(); await loadQuestionnaires(); }
