async function saveTprmAssessment(event) { event.preventDefault(); const id = $('tprmAssessmentId').value; const row = tprmRows.find(item => String(item.id) === id); if (!row) return; const values = updateTprmAssessmentFromInputs(); if (values.total === null) { $('tprmAssessmentStatus').textContent = 'Complete all CIA indicators with a score from 1 to 5'; return; } const dueDiligenceAssessment = Object.fromEntries(ciaAssessmentTypes[activeCiaAssessmentType].fields.map(field => [field.key, Number($(`tprmAssessment${field.input}`).value)])); Object.assign(dueDiligenceAssessment, { assessmentType: activeCiaAssessmentType, confidentiality: values.confidentiality, integrity: values.integrity, availability: values.availability, riskScore: values.total, riskTier: ciaRiskTier(values.total) }); const response = await fetch(`/api/tprm/${id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...row, dueDiligenceAssessment, riskLevel: riskLevelForTier(dueDiligenceAssessment.riskTier), assessmentStatus: 'Complete', nextReview: $('tprmAssessmentNextReview')?.value || $('tprmNextReviewDate')?.value || '', relationshipStatus: row.relationshipStatus || 'Active' }) }); $('tprmAssessmentStatus').textContent = response.ok ? 'CIA assessment saved' : (await response.json().catch(() => ({}))).error || 'Save failed'; if (response.ok) { $('tprmAssessmentModal').close(); await loadTprmRows(); } }
