function riskRatingFromScore(likelihood, impact) { const score = Number(likelihood || 0) * Number(impact || 0); return score >= 20 ? 'Very High' : score >= 11 ? 'High' : score >= 5 ? 'Medium' : score >= 3 ? 'Low' : score ? 'Very Low' : ''; }
function updateRiskCalculations() { const assetValue = ['rmAssetConfidentiality', 'rmAssetIntegrity', 'rmAssetAvailability'].map(id => Number($(id).value) || 0).reduce((sum, value) => sum + value, 0); $('rmAssetValue').value = assetValue || ''; $('rmRiskRating').value = riskRatingFromScore($('rmLikelihood').value, $('rmImpact').value); $('rmResidualRating').value = riskRatingFromScore($('rmResidualLikelihood').value, $('rmResidualImpact').value); }
function synchronizeRiskDropdowns() { const fields = [['riskCategory', 'riskCategory'], ['effectedAsset', 'effectedAsset'], ['deviceName', 'deviceName'], ['riskOwner', 'riskOwner'], ['treatmentAction', 'treatmentAction']]; const source = [...riskDropdowns, ...fallbackRiskDropdowns]; fields.forEach(([field, rowField]) => riskManagementRows.forEach(row => { if (row[rowField]) source.push({ fieldName: field, optionValue: row[rowField], sortOrder: 999 }); })); riskDropdowns = [...new Map(source.filter(row => row.optionValue).map(row => [`${row.fieldName}:${row.optionValue}`, row])).values()]; }
function renderRiskDropdownControls() { const fields = [['riskCategory', 'rmRiskCategory', 'Select category'], ['effectedAsset', 'rmEffectedAsset', 'Select asset'], ['deviceName', 'rmDeviceName', 'Select device'], ['riskOwner', 'rmRiskOwner', 'Select owner'], ['treatmentAction', 'rmTreatmentAction', 'Select treatment']]; synchronizeRiskDropdowns(); fields.forEach(([field, id, placeholder]) => { const old = $(id); const current = old.value; const options = riskDropdowns.filter(row => row.fieldName === field).sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0) || String(a.optionValue).localeCompare(String(b.optionValue))); const select = document.createElement('select'); select.id = id; select.required = !['rmRiskOwner', 'rmTreatmentAction'].includes(id); select.innerHTML = `<option value="">${placeholder}</option>${options.map(row => `<option value="${escapeHtml(row.optionValue)}">${escapeHtml(row.optionValue)}</option>`).join('')}`; select.value = current; old.replaceWith(select); }); }
function nextRiskIdPreview() { const numbers = riskManagementRows.map(row => Number(String(row.riskId || '').replace(/[^0-9]/g, ''))).filter(Number.isFinite); return `CSR - ${String((numbers.length ? Math.max(...numbers) : 0) + 1).padStart(3, '0')}`; }
function openRiskManagementModal() { const modal = $('riskManagementModal'); if (modal && !modal.open) modal.showModal(); }
function resetRiskManagementForm() { $('riskRegisterForm').reset(); $('riskRegisterOriginalId').value = ''; $('rmRiskId').value = nextRiskIdPreview(); $('riskRegisterFormTitle').textContent = 'New risk'; $('riskRegisterStatus').textContent = 'Risk ID generated automatically'; $('riskRegisterSubmit').textContent = 'Save risk'; updateRiskCalculations(); }
function fillRiskManagementForm(row) { riskManagementFields.forEach(field => { const element = $(`rm${field.charAt(0).toUpperCase()}${field.slice(1)}`); if (element) element.value = row[field] ?? ''; }); $('riskRegisterOriginalId').value = row.riskId; $('riskRegisterFormTitle').textContent = `Edit ${row.riskId}`; $('riskRegisterSubmit').textContent = 'Update risk'; openRiskManagementModal(); }
function renderRiskDashboard() { const total = riskManagementRows.length; const high = riskManagementRows.filter(row => ['High', 'Very High'].includes(row.riskRating)).length; const residual = riskManagementRows.filter(row => ['High', 'Very High'].includes(row.residualRating)).length; const today = new Date().toISOString().slice(0, 10); const overdue = riskManagementRows.filter(row => row.deadline && String(row.deadline).slice(0, 10) < today).length; const countBy = field => riskManagementRows.reduce((result, row) => { const key = row[field] || 'Unassigned'; result[key] = (result[key] || 0) + 1; return result; }, {}); const ratings = countBy('riskRating'); const treatments = countBy('treatmentAction'); const values = riskManagementRows.map(row => Number(row.assetValue)).filter(Number.isFinite); const average = values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : 0; $('riskTotalValue').textContent = total; $('riskHighValue').textContent = high; $('riskResidualValue').textContent = residual; $('riskOverdueValue').textContent = overdue; $('riskManagementCount').textContent = `${total} risk${total === 1 ? '' : 's'}`; $('riskAssetValueAverage').textContent = average.toFixed(1); const summary = (data, totalCount) => Object.entries(data).sort((a, b) => b[1] - a[1]).map(([label, count]) => `<div class="risk-summary-row"><span>${escapeHtml(label)}</span><strong>${count}</strong><i><b style="width:${count / Math.max(totalCount, 1) * 100}%"></b></i></div>`).join('') || '<small>No data available.</small>'; $('riskRatingSummary').innerHTML = summary(ratings, total); $('riskTreatmentSummary').innerHTML = summary(treatments, total); }
function renderRiskRegister() { const query = $('riskRegisterSearch').value.toLowerCase(); const category = $('riskRegisterCategoryFilter').value; const rating = $('riskRegisterRatingFilter').value; const treatment = $('riskRegisterTreatmentFilter').value; const filtered = riskManagementRows.filter(row => (category === 'all' || row.riskCategory === category) && (rating === 'all' || row.riskRating === rating) && (treatment === 'all' || row.treatmentAction === treatment) && riskManagementFields.map(field => row[field]).join(' ').toLowerCase().includes(query)); const rows = filtered.sort((left, right) => { const a = left[riskRegisterSort.field] ?? ''; const b = right[riskRegisterSort.field] ?? ''; const numeric = Number(a) - Number(b); const result = a !== '' && b !== '' && Number.isFinite(numeric) && numeric !== 0 ? numeric : String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: 'base' }); return riskRegisterSort.direction === 'asc' ? result : -result; }); riskRegisterPage = Math.min(Math.max(1, riskRegisterPage), Math.max(1, Math.ceil(rows.length / 20))); const visibleRows = rows.slice((riskRegisterPage - 1) * 20, riskRegisterPage * 20); $('riskRegisterHead').innerHTML = `<tr>${riskRegisterColumns.map(column => `<th><button type="button" class="risk-sort-button ${riskRegisterSort.field === column.field ? 'active' : ''}" data-rm-sort="${column.field}">${column.label}<span>${riskRegisterSort.field === column.field ? (riskRegisterSort.direction === 'asc' ? '^' : 'v') : '<>'}</span></button></th>`).join('')}<th>Actions</th></tr>`; $('riskRegisterBody').innerHTML = visibleRows.map(row => `<tr>${riskRegisterColumns.map(column => { const value = row[column.field]; const content = column.field === 'riskRating' || column.field === 'residualRating' ? `<span class="risk-rating ${String(value || '').toLowerCase().replaceAll(' ', '-')}">${escapeHtml(value || '-')}</span>` : escapeHtml(value || '-'); return `<td>${content}</td>`; }).join('')}<td><button class="attachment-action-button" type="button" data-rm-edit="${escapeHtml(row.riskId)}">Edit</button><button class="attachment-action-button danger" type="button" data-rm-delete="${escapeHtml(row.riskId)}">Delete</button></td></tr>`).join('') || `<tr><td colspan="${riskRegisterColumns.length + 1}">No risks found.</td></tr>`; let pagination = $('riskRegisterPagination'); if (!pagination) { pagination = document.createElement('div'); pagination.id = 'riskRegisterPagination'; pagination.className = 'assessment-pagination'; $('riskRegisterBody').closest('.excel-wrap').appendChild(pagination); } pagination.innerHTML = rows.length > 20 ? `<button type="button" data-risk-register-page="${riskRegisterPage - 1}" ${riskRegisterPage === 1 ? 'disabled' : ''}>Previous</button><span>Page ${riskRegisterPage} of ${Math.ceil(rows.length / 20)} · ${rows.length} risks</span><button type="button" data-risk-register-page="${riskRegisterPage + 1}" ${riskRegisterPage === Math.ceil(rows.length / 20) ? 'disabled' : ''}>Next</button>` : ''; }
