async function importRiskRegister(file) { try { const payload = JSON.parse(await file.text()); const rows = payload.riskRegister || payload.risks || []; const dropdowns = payload.dropdowns || []; for (const option of dropdowns) { await fetch('/api/risk-management/dropdowns', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(option) }); } for (const row of rows) { const data = { ...row }; delete data.riskId; delete data.assetValue; delete data.riskRating; delete data.residualRating; const response = await fetch('/api/risk-management', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); if (!response.ok) throw new Error(`Import failed for ${row.riskId || 'row'}`); } await loadRiskManagement(); $('riskRegisterStatus').textContent = `${rows.length} risk(s) imported`; } catch (error) { $('riskRegisterStatus').textContent = error.message || 'Import failed'; } finally { $('riskRegisterImportInput').value = ''; } }
function populateRiskRegisterFilters() { [['riskRegisterCategoryFilter', 'riskCategory', 'All categories'], ['riskRegisterRatingFilter', 'riskRating', 'All ratings'], ['riskRegisterTreatmentFilter', 'treatmentAction', 'All treatments']].forEach(([id, field, label]) => { const select = $(id); const selected = select.value; const options = [...new Set(riskManagementRows.map(row => row[field]).filter(Boolean))].sort(); select.innerHTML = `<option value="all">${label}</option>${options.map(value => `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('')}`; select.value = options.includes(selected) ? selected : 'all'; }); }
function renderRiskIndicators() {
  const actions = row => `<td><button class="attachment-action-button" type="button" data-indicator-edit="${row.id}">Edit</button><button class="attachment-action-button danger" type="button" data-indicator-delete="${row.id}">Delete</button></td>`;
  const group = type => riskIndicators.filter(row => row.indicator_type === type);
  const cia = group('CIA'); const ciaScores = [...new Set(cia.map(row => row.score))];
  $('riskIndicatorsCiaBody').innerHTML = ciaScores.map(score => { const rows = cia.filter(row => row.score === score); return `<tr><td class="indicator-score">${score}</td>${['Confidentiality', 'Integrity', 'Availability'].map(label => { const row = rows.find(item => item.label === label) || {}; return `<td>${escapeHtml(row.description || '-')}</td>`; }).join('')}${actions(rows[0] || {})}</tr>`; }).join('');
  const impact = group('Impact'); const impactScores = [...new Set(impact.map(row => row.score))];
  $('riskIndicatorsImpactBody').innerHTML = impactScores.map(score => { const rows = impact.filter(row => row.score === score); const description = rows.find(row => row.label === 'Deskripsi Dampak'); return `<tr><td class="indicator-score">${score}</td><td>${escapeHtml(description?.description || '-')}</td>${['Layanan', 'Keuangan', 'Reputasi', 'Hukum'].map(label => `<td>${escapeHtml(rows.find(row => row.label === label)?.description || '-')}</td>`).join('')}${actions(description || rows[0] || {})}</tr>`; }).join('');
  $('riskIndicatorsFrequencyBody').innerHTML = group('Frequency').map(row => `<tr><td class="indicator-score">${row.sort_order + 1}</td><td><strong>${escapeHtml(row.label)}</strong><br>${escapeHtml(row.description)}</td>${actions(row)}</tr>`).join('');
  $('riskIndicatorsMatrixBody').innerHTML = group('Matrix').map(row => { let levels = []; try { levels = JSON.parse(row.description); } catch (error) { levels = []; } return `<tr><td class="indicator-score">${escapeHtml(row.label)}</td>${levels.map(level => `<td>${escapeHtml(level || '-')}</td>`).join('')}${actions(row)}</tr>`; }).join('');
}
