async function saveRiskDropdown(event) { event.preventDefault(); const id = $('riskDropdownId').value; const isFallback = id.startsWith('fallback-'); const data = { fieldName: $('riskDropdownField').value, optionValue: $('riskDropdownValue').value, sortOrder: $('riskDropdownSort').value }; const response = await fetch(id && !isFallback ? `/api/risk-management/dropdowns/${id}` : '/api/risk-management/dropdowns', { method: id && !isFallback ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); if (response.ok) await loadRiskManagement(); }
