async function loadRiskManagement() { const [registerResponse, indicatorResponse, dropdownResponse] = await Promise.all([fetch('/api/risk-management', { cache: 'no-store' }), fetch('/api/risk-management/indicators', { cache: 'no-store' }), fetch('/api/risk-management/dropdowns', { cache: 'no-store' })]); if (!registerResponse.ok || !indicatorResponse.ok) throw new Error('Risk management data unavailable'); riskManagementRows = await registerResponse.json(); riskIndicators = await indicatorResponse.json(); riskDropdowns = dropdownResponse.ok ? await dropdownResponse.json() : []; ensureRiskDropdownManager(); ensureDeviceDropdownFieldOption(); renderRiskDropdownControls(); $('rmRiskId').readOnly = true; populateRiskRegisterFilters(); renderRiskDashboard(); renderRiskRegister(); renderRiskIndicators(); renderRiskDropdownManager(); updateRiskCalculations(); }
