  const rows = sortAssessmentRows(allControls().filter(item => (filter === 'all' || item.fn.id === filter) && `${item.fn.name} ${item.name} ${item.code} ${item.category}`.toLowerCase().includes(query)), csfSort);
  csfCorePage = renderAssessmentPagination('csfCorePagination', csfCorePage, rows.length); const visibleRows = rows.slice((csfCorePage - 1) * 20, csfCorePage * 20);
  $('csfTableBody').innerHTML = visibleRows.map(item => `<tr><td>${item.fn.id}<br>${item.fn.name}</td><td>${item.category || 'CSF Core'}</td><td>${item.subcategory}</td><td>${item.implementation}</td><td>${item.references}</td><td>${attachmentControl(item, 'policy')}</td><td><textarea class="reasoning-input" data-reasoning="policy-${item.id}" placeholder="Why this policy score?"></textarea></td><td>${attachmentControl(item, 'practice')}</td><td><textarea class="reasoning-input" data-reasoning="practice-${item.id}" placeholder="Why this practice score?"></textarea></td><td><button class="attachment-action-button" type="button" data-open-csf-manager="${escapeHtml(item.id)}">Manage</button></td></tr>`).join('') || '<tr><td colspan="10">No CSF controls match this filter.</td></tr>';
  renderScoreControls();
  document.querySelectorAll('[data-reasoning]').forEach(input => { const key = input.dataset.reasoning; input.value = state.notes[key] || ''; input.addEventListener('input', () => { state.notes[key] = input.value; save(); }); });
  document.querySelectorAll('[data-assessment-score]').forEach(button => button.addEventListener('click', () => { const score = Number(button.dataset.assessmentScore); if (button.dataset.scoreType === 'policy') state.policyScores[button.dataset.control] = score; else state.practiceScores[button.dataset.control] = score; save(); renderCsfTable(); renderOverview(); }));
  document.querySelectorAll('[data-attachment]').forEach(input => input.addEventListener('change', event => uploadAttachment(event.target)));
  document.querySelectorAll('[data-replace-attachment]').forEach(input => input.addEventListener('change', event => replaceAttachment(event.target)));
  document.querySelectorAll('[data-open-csf-manager]').forEach(button => button.addEventListener('click', () => openCsfManager(button.dataset.openCsfManager)));
  document.querySelectorAll('#csfTableBody [data-delete-attachment]').forEach(button => button.addEventListener('click', () => deleteAttachment(button.dataset.deleteAttachment, Number(button.dataset.attachmentIndex))));
  document.querySelectorAll('#csfTableBody [data-open-attachment]').forEach(button => button.addEventListener('click', () => openAttachment(button.dataset.openAttachment, Number(button.dataset.attachmentIndex))));
  document.querySelectorAll('#csfTableBody [data-download-attachment]').forEach(button => button.addEventListener('click', () => downloadAttachment(button.dataset.downloadAttachment, Number(button.dataset.attachmentIndex))));
