function sortAssessmentRows(rows, sortField) {
  return [...rows].sort((first, second) => {
    const firstValue = sortField === 'function' ? first.fn?.name : first[sortField];
    const secondValue = sortField === 'function' ? second.fn?.name : second[sortField];
    return String(firstValue || '').localeCompare(String(secondValue || ''), undefined, { numeric: true, sensitivity: 'base' });
  });
}
